using System;
using System.Collections;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "HurricaneActiveEffect", menuName = "Data/Battle/Effects/Austra/HurricaneActive Effect")]
public class HurricaneActiveEffect : Effect
{
	[NonSerialized]
	private int drawAmount;

	[SerializeField]
	private DrawAction drawAction;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private DefaultEffectAction boostEffectAction;

	[SerializeField]
	private OmenLogic playerOmenLogic;

	public string GetDrawActionDescription()
	{
		return drawAction.GetActionDescription(1).LowercaseFirst();
	}

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), GetDrawActionDescription());
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		drawAmount = 0;
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn && ReferenceSingleton<GameStateManager>.Instance.EndPlayerTurnState.EndTurnActivations.Count == 0)
		{
			if (drawAmount == 0)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(HurricaneDodgeActivate());
				ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			}
			drawAmount++;
		}
		return amount;
	}

	private IEnumerator HurricaneDodgeActivate()
	{
		if (!ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAllEnemiesDefeated())
		{
			omenLogic.ActivateOmen(drawAction, drawAmount, null, null);
			drawAmount = 0;
			yield return InvokeAlternatives.WaitOneFrame();
		}
	}
}
